-- ── 1,686 reviews across the 135 active bulk businesses (10-15 each) ──
-- Looked up by photo_url so this works regardless of the businesses'
-- actual ids.


-- ── Recalculate average_rating for every business that just got reviews ──
UPDATE businesses b SET average_rating = (
  SELECT COALESCE(AVG(rating), 0) FROM reviews WHERE business_id = b.id
) WHERE b.photo_url LIKE '/uploads/bulk-%';
